@lru_cache(maxsize=1)
def archive():
    return zipfile.ZipFile(io.BytesIO(base64.b85decode(_PAYLOAD)))
@lru_cache(maxsize=1)
def html():
    z=archive()
    entries={n:[mimetypes.guess_type(n)[0] or 'application/octet-stream',base64.b64encode(z.read(n)).decode()] for n in z.namelist() if n not in ('game.js','game.css','template.html')}
    boot="window.__ASSETS__={};for(const [p,[type,data]] of Object.entries("+json.dumps(entries,separators=(',',':'))+")){const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));window.__ASSETS__[p]=URL.createObjectURL(new Blob([bytes],{type}));}document.getElementById('source').href=window.__ASSETS__['source.zip'];"
    return z.read('template.html').decode().replace('__CSS__',z.read('game.css').decode()).replace('__BOOT__',boot).replace('__JS__',z.read('game.js').decode().replace('</script',r'<\/script'))
def main():
    if '--extract-source' in sys.argv:
        from pathlib import Path
        i=sys.argv.index('--extract-source');p=Path(sys.argv[i+1] if len(sys.argv)>i+1 else 'knight-source.zip');p.write_bytes(archive().read('source.zip'));print(p);return
    if 'google.colab' in sys.modules:
        from IPython.display import HTML,display
        import html as escape_html
        display(HTML('<iframe style="width:100%;height:1050px;border:0" allow="autoplay;fullscreen" srcdoc="'+escape_html.escape(html(),quote=True)+'"></iframe>'));return
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        running=get_script_run_ctx(suppress_warning=True) is not None
    except ImportError:running=False
    if running:
        import streamlit as st
        import streamlit.components.v1 as components
        st.set_page_config(page_title='기사 전투',layout='wide')
        components.html(html(),height=1080,scrolling=True);return
    from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path.split('?')[0] not in ('/','/index.html'):
                self.send_error(404);return
            data=html().encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
    port=int(sys.argv[sys.argv.index('--port')+1]) if '--port' in sys.argv else 8000
    print(f'브라우저에서 http://localhost:{port} 를 여세요.',flush=True)
    try:ThreadingHTTPServer(('0.0.0.0',port),Handler).serve_forever()
    except KeyboardInterrupt:pass
if __name__=='__main__':main()
